import numpy as np
from scipy.optimize import least_squares
def sim(row,Cd,g,dt=0.01):
    m=row['mass'];r=row['radius'];rho=row['air_density']
    k=0.5*rho*Cd[row['shape']]*np.pi*r*r/m
    x=0;y=row['height'];a=np.radians(row['angle']);vx=row['speed']*np.cos(a);vy=row['speed']*np.sin(a);t=0
    while y>0:
        v=np.hypot(vx,vy)
        vx+=-k*v*vx*dt;vy+=(-g-k*v*vy)*dt;x+=vx*dt;y+=vy*dt;t+=dt
    return t,x,np.hypot(vx,vy)
sub=df[((df.run>70)&(df.run<124))|(df.run>146)].groupby('set').head(2)
def res(p):
    Cd={'sphere':p[0],'cube':p[1],'cylinder':p[2]}
    out=[]
    for _,r in sub.iterrows():
        t,x,v=sim(r,Cd,p[3])
        out+=[(t-r.flight_time)/r.flight_time,(v-r.impact_speed)/r.impact_speed]
        if r.distance>0: out.append((x-r.distance)/r.distance)
    return out
f=least_squares(res,[0.5,1,0.8,9.8],diff_step=1e-3)
print(f.x,np.sqrt(np.mean(np.square(f.fun))))
